def csv_rows(text):
    rows = []
    i = 0
    n = len(text)
    while i < n:
        row = []
        while True:
            # Parse a single field
            if i < n and text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field_chars = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Doubled quote: escaped quote
                            field_chars.append('"')
                            i += 2
                        else:
                            # Closing quote
                            i += 1
                            break
                    else:
                        field_chars.append(text[i])
                        i += 1
                row.append(''.join(field_chars))
            else:
                # Unquoted field
                field_chars = []
                while i < n:
                    if text[i] == ',':
                        break
                    if text[i] == '\r':
                        if i + 1 < n and text[i + 1] == '\n':
                            break
                        else:
                            break
                    if text[i] == '\n':
                        break
                    field_chars.append(text[i])
                    i += 1
                row.append(''.join(field_chars))

            # After parsing a field, check what's next
            if i < n and text[i] == ',':
                i += 1  # skip comma, continue to next field in same row
                continue
            elif i < n and text[i] == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                break
            elif i < n and text[i] == '\n':
                i += 1
                break
            else:
                # End of input
                break

        rows.append(row)

    return rows
